def w(name, header, rows):
    with open(os.path.join(D, name), 'w', encoding='utf-8', newline='') as f:
        wr = csv.writer(f)
        wr.writerow(header)
        for r in rows:
            wr.writerow(r)
    print(name, len(rows))


